   569        if (!coord_count || coord_count != gvar_table->axisCount) return true;
   570
   571        const GlyphVarData &var_data = gvar_table->get_glyph_var_data (glyph);
   572        if (!var_data.has_data ()) return true;
   573        hb_vector_t<unsigned int> shared_indices;
   574        GlyphVarData::tuple_iterator_t iterator;
   575        if (!GlyphVarData::get_tuple_iterator (&var_data,
   576                                               gvar_table->get_glyph_var_data_length (glyph),
   577                                               gvar_table->axisCount,
   578                                               shared_indices,
   579                                               &iterator))
   580          return true; /* so isn't applied at all */
   581
