   592        {
   593          float scalar = iterator.current_tuple->calculate_scalar (coords, coord_count, shared_tuples.as_array ());
   594          if (scalar == 0.f) continue;
   595          const HBUINT8 *p = iterator.get_serialized_data ();
   596          unsigned int length = iterator.current_tuple->get_data_size ();
   597          if (unlikely (!iterator.in_range (p, length)))
   598            return false;
   599
